const update = $input.first().json.update || $input.first().json;
const callback = update.callback_query;
const message = callback?.message || update.message;
if (!message || message.chat?.type !== 'private') return [];
if (!callback && typeof message.text !== 'string') return [];
const result = {
  chat_id: String(message.chat.id), action: 'help', sport: '', team_key: '',
  label: '', aliases: [], daily: false, route: 'home',
  is_callback: Boolean(callback),
  reply: `Welcome to Sports Radar 👋

Follow your favourite teams and F1 drivers, and get a personalised preview before they compete, what to expect, who to watch, and the key matchups.

Which sport would you like to follow first?`
};
// These values are the contract between the existing Telegram buttons and the router.
const exactRoutes = {
  'sport:football': 'football_menu', 'sport:basketball': 'nba_menu',
  'sport:f1': 'f1_menu', 'menu:follows': 'my_follows', 'menu:sports': 'home'
};
if (callback) {
  const data = typeof callback.data === 'string' ? callback.data : '';
  result.route = exactRoutes[data] || 'home';
  if (/^league:(PL|PD|SA|BL1|FL1)$/.test(data)) result.route = 'football_teams';
  if (/^follow:football:[1-9][0-9]*$/.test(data)) result.route = 'follow_football';
  if (/^follow:basketball:[1-9][0-9]*$/.test(data)) result.route = 'follow_nba';
  if (/^follow:f1:[a-zA-Z0-9_-]{1,48}$/.test(data)) result.route = 'follow_f1';
  const manage = /^manage:follows:([0-9]{1,6})$/.exec(data);
  if (manage) { result.route = 'manage_follows'; result.page = Number(manage[1]); }
  // Short sport codes keep callback data within Telegram's 64-byte limit.
  const removal = /^unfollow:([fbr]):([a-zA-Z0-9_-]{1,48})$/.exec(data);
  if (removal) {
    result.route = 'unfollow'; result.action = 'unfollow';
    result.sport = {f:'football',b:'basketball',r:'f1'}[removal[1]];
    result.team_key = removal[2];
  }

} else {
  const command = message.text.trim().split(/\s+/)[0].toLowerCase().split('@')[0];
  if (command === '/myteams') result.route = 'my_follows';
  // Retain access to the existing briefing subworkflow; configure/test 02 separately.
  if (command === '/events') {
    result.route = 'events'; result.action = 'events'; result.reply = '';
  }
}
if (!callback) {
  const parts = message.text.trim().toLowerCase().split(/\s+/);
  const command = parts[0].split('@')[0];

  if (command === '/daily') {
    if (parts.length === 2 && ['on', 'off'].includes(parts[1])) {
      result.route = 'daily';
      result.action = 'daily';
      result.daily = parts[1] === 'on';
      result.reply = result.daily
        ? '✅ Daily digest preference saved: ON.'
        : '🔕 Daily digest preference saved: OFF.';
    } else {
      result.route = 'home';
      result.reply = 'Use /daily on to enable the daily digest, or /daily off to disable it.';
    }
  }
}
if (callback?.data === 'menu:events') {
  result.route = 'events';
  result.action = 'events';
  result.reply = '';
}
if (!callback) {
  const tokens = message.text.trim().toLowerCase().split(/\s+/);
  const command = tokens[0].split('@')[0];

  if (['/previews', '/reminders', '/quiet', '/alerts'].includes(command)) {
    result.route = 'alert_settings';
    result.alert_command = command.slice(1);
    result.alert_value =
      tokens.length === 2 && ['on', 'off'].includes(tokens[1])
        ? tokens[1]
        : 'status';
  }
}
if (!callback) {
  const parts = message.text.trim().toLowerCase().split(/\s+/);
  const cmd = parts[0].split('@')[0];
  const known = ['/start','/help','/myteams','/events','/daily','/alerts','/previews','/reminders','/quiet','/demoerror'];
  if (!known.includes(cmd)) {
    result.route='home';
    result.reply='Unknown command. Use /start for the menu, /events for upcoming events, /myteams for saved follows, /daily on or /daily off, and /alerts for preview and reminder settings.';
  } else if (cmd==='/demoerror') {
    result.route='demo_failure';result.reply='';
  } else if (cmd==='/help') {
    result.reply='Sports Radar commands\n\n/start — home menu\n/events — next seven days\n/myteams — saved follows\n/daily on or /daily off — daily digest\n/previews on or /previews off — previews\n/reminders on or /reminders off — start reminders\n/quiet on or /quiet off — overnight alerts\n/alerts — current alert settings\n\nChoose teams and drivers using the menu buttons.';
  }
}
return [{json: result}];

const data = $input.first().json;
const update = $('Telegram message').first().json;
const callback = update.callback_query;
if (!callback || callback.message?.chat?.type !== 'private') return [];
const league = callback.data?.split(':')[1];
const labels = {PL:'Premier League',PD:'La Liga',SA:'Serie A',BL1:'Bundesliga',FL1:'Ligue 1'};
if (!labels[league] || data.competition?.code !== league) {
  throw new Error('The returned league does not match the selected button. Check Get league teams URL.');
}
if (!Array.isArray(data.teams)) throw new Error('The API did not return a team list.');
const seen = new Set();
const teams = data.teams.map(t => {
  if (!Number.isSafeInteger(t.id) || t.id <= 0 || !t.name || seen.has(t.id)) {
    throw new Error('The API returned an invalid or duplicate team.');
  }
  seen.add(t.id);
  return {id:t.id, label:String(t.shortName || t.name), name:String(t.name)};
}).sort((a,b) => a.label.localeCompare(b.label, 'en'));
// These menu layouts cover 18- and 20-team leagues. Fail explicitly if coverage changes.
if (![18,20].includes(teams.length)) {
  throw new Error('Received ' + teams.length + ' teams. This menu needs an updated layout before sending.');
}
return [{json:{
  chat_id:String(callback.message.chat.id),
  callback_id:callback.id,
  league,
  team_count:teams.length,
  teams,
  text:'⚽ ' + labels[league] + '\n\nWhich team would you like to follow?'
}}];

const data = $input.first().json;
const callback = $('Telegram message').first().json.callback_query;

if (!callback || callback.message?.chat?.type !== 'private') return [];
if (callback.data !== 'sport:basketball') return [];

if (data.errors && Object.keys(data.errors).length) {
  throw new Error('NBA API error: ' + JSON.stringify(data.errors));
}

if (!Array.isArray(data.response)) {
  throw new Error('The NBA API did not return a team list.');
}

const seen = new Set();

const teams = data.response
  .filter(t => t.nbaFranchise === true && t.allStar !== true)
  .map(t => {
    if (
      !Number.isSafeInteger(t.id) ||
      t.id <= 0 ||
      typeof t.name !== 'string' ||
      !t.name.trim() ||
      seen.has(t.id)
    ) {
      throw new Error('The NBA API returned an invalid or duplicate team.');
    }

    seen.add(t.id);

    const name = t.name.trim();
    const label =
      typeof t.nickname === 'string' && t.nickname.trim()
        ? t.nickname.trim()
        : name;

    return { id: t.id, name, label };
  })
  .sort((a, b) => a.name.localeCompare(b.name, 'en'));

if (teams.length !== 30) {
  throw new Error(
    'Expected 30 NBA franchises but found ' + teams.length + '.'
  );
}

return [{
  json: {
    chat_id: String(callback.message.chat.id),
    teams,
    team_count: teams.length,
    text: '🏀 NBA\n\nWhich team would you like to follow?'
  }
}];

const data = $input.first().json;
const callback = $('Telegram message').first().json.callback_query;
if (!callback || callback.message?.chat?.type !== 'private') return [];
if (callback.data !== 'sport:f1') return [];
const races = data.MRData?.RaceTable?.Races;
if (!Array.isArray(races) || races.length !== 1 || !Array.isArray(races[0].Results)) {
  throw new Error('No latest-race results returned. Check Get F1 drivers uses /current/last/results/.');
}
const race = races[0];
if (Number(data.MRData.total) !== race.Results.length) {
  throw new Error('The API response is incomplete. Fetch all results before building the menu.');
}
const seen = new Set();
const drivers = race.Results.map(result => {
  const d = result.Driver;
  if (!d || typeof d.driverId !== 'string' || !/^[a-zA-Z0-9_-]{1,48}$/.test(d.driverId) ||
      typeof d.givenName !== 'string' || !d.givenName.trim() ||
      typeof d.familyName !== 'string' || !d.familyName.trim() || seen.has(d.driverId)) {
    throw new Error('The F1 API returned an invalid or duplicate driver.');
  }
  seen.add(d.driverId);
  return {id:d.driverId,name:d.givenName.trim()+' '+d.familyName.trim(),
          label:d.familyName.trim(),constructor:result.Constructor?.name || ''};
}).sort((a,b) => a.label.localeCompare(b.label,'en'));
const labelCounts = new Map();
for (const d of drivers) labelCounts.set(d.label,(labelCounts.get(d.label)||0)+1);
for (const d of drivers) if (labelCounts.get(d.label)>1) d.label=d.name;
// Current layout has 22 slots; don't silently omit drivers if the field changes.
if (drivers.length !== 22) {
  throw new Error('This menu expects 22 drivers; the latest race returned '+drivers.length+'. Check the results and menu layout.');
}
return [{json:{chat_id:String(callback.message.chat.id),drivers,driver_count:drivers.length,
  season:race.season,round:race.round,race_name:race.raceName,race_date:race.date,
  text:'🏎️ Formula 1\n\nWhich driver would you like to follow?\n\nDrivers from the latest completed race.'}}];

const update = $('Telegram message').first().json;
const callback = update.callback_query;
if (!callback || callback.message?.chat?.type !== 'private') return [];
const match = /^follow:football:([1-9][0-9]*)$/.exec(callback.data || '');
if (!match) throw new Error('This is not a football team selection.');
const team = $input.first().json;
const expectedId = Number(match[1]);
if (!Number.isSafeInteger(expectedId) || team.id !== expectedId || typeof team.name !== 'string' || !team.name.trim()) {
  throw new Error('The API did not return the selected team. Nothing has been saved.');
}
const label = typeof team.shortName === 'string' && team.shortName.trim() ? team.shortName.trim() : team.name.trim();
const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const aliases = [...new Set([team.name, label, team.tla].filter(s=>typeof s==='string').map(norm).filter(Boolean))];
return [{json:{
  chat_id:String(callback.message.chat.id),
  action:'follow',
  sport:'football',
  team_key:String(expectedId),
  label,
  aliases,
  daily:false,
  reply:'✅ You’re now following ' + label + '.\n\nYour choice is saved. You can add more teams below.'
}}];

const callback = $('Telegram message').first().json.callback_query;
if (!callback || callback.message?.chat?.type !== 'private') return [];
const match = /^follow:basketball:([1-9][0-9]*)$/.exec(callback.data || '');
if (!match) throw new Error('This is not an NBA team selection.');
const data = $input.first().json;
if (data.errors && Object.keys(data.errors).length) {
  throw new Error('NBA API error: ' + JSON.stringify(data.errors));
}
const expectedId = Number(match[1]);
if (!Number.isSafeInteger(expectedId) || !Array.isArray(data.response) || data.response.length !== 1) {
  throw new Error('The NBA API did not return one selected team. Nothing has been saved.');
}
const team = data.response[0];
if (team.id !== expectedId || team.nbaFranchise !== true || team.allStar === true || typeof team.name !== 'string' || !team.name.trim()) {
  throw new Error('The NBA API did not return the selected NBA franchise. Nothing has been saved.');
}
const label = team.name.trim();
const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const aliases = [...new Set([team.name,team.nickname,team.code].filter(s=>typeof s==='string').map(norm).filter(Boolean))];
return [{json:{
  chat_id:String(callback.message.chat.id),
  action:'follow',sport:'basketball',team_key:String(expectedId),label,aliases,daily:false,
  reply:'✅ You’re now following ' + label + '.\n\nYour choice is saved. You can add more teams below.'
}}];

const callback = $('Telegram message').first().json.callback_query;
if (!callback || callback.message?.chat?.type !== 'private') return [];
const match = /^follow:f1:([a-zA-Z0-9_-]{1,48})$/.exec(callback.data || '');
if (!match) throw new Error('This is not an F1 driver selection.');
const data = $input.first().json;
const drivers = data.MRData?.DriverTable?.Drivers;
if (!Array.isArray(drivers) || drivers.length !== 1 || Number(data.MRData.total) !== 1) {
  throw new Error('The F1 API did not return one selected driver. Nothing has been saved.');
}
const driver = drivers[0];
if (driver.driverId !== match[1] ||
    typeof driver.givenName !== 'string' || !driver.givenName.trim() ||
    typeof driver.familyName !== 'string' || !driver.familyName.trim()) {
  throw new Error('The F1 API did not return the selected driver. Nothing has been saved.');
}
const label = driver.givenName.trim() + ' ' + driver.familyName.trim();
const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const aliases = [...new Set([label,driver.familyName,driver.code].filter(s=>typeof s==='string').map(norm).filter(Boolean))];
return [{json:{
  chat_id:String(callback.message.chat.id),
  action:'follow',sport:'f1',team_key:driver.driverId,label,aliases,daily:false,
  reply:'✅ You’re now following ' + label + '.\n\nYour choice is saved. You can add more drivers below.'
}}];

const data = $input.first().json;
const chat_id = String(data.chat_id || '');
if (!/^[0-9]+$/.test(chat_id)) throw new Error('Missing private chat ID.');
let prefs = data.prefs;
if (typeof prefs === 'string') prefs = JSON.parse(prefs);
if (!Array.isArray(prefs)) throw new Error('Could not read your saved follows.');
const escape = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const request = $('Understand command').first().json;
const button = (text, data) => ({text, additionalFields:{callback_data:data}});
const homeButtons = [
  button('⚽ Football','sport:football'),button('🏀 NBA','sport:basketball'),
  button('🏎️ Formula 1','sport:f1'),button('🔄 Refresh my follows','menu:follows')
];

if (request.route === 'manage_follows') {
  const sports = {football:{code:'f',icon:'⚽'},basketball:{code:'b',icon:'🏀'},f1:{code:'r',icon:'🏎️'}};
  const entries = prefs.map(p => {
    const sport = sports[p.sport];
    const key = String(p.team_key || '');
    if (!sport || !/^[a-zA-Z0-9_-]{1,48}$/.test(key)) {
      throw new Error('A saved follow has an unsupported identifier. No choices were removed.');
    }
    const label = String(p.label || key).replace(/\s+/g,' ').trim().slice(0,150);
    return {sport:p.sport, label, callback:'unfollow:'+sport.code+':'+key, icon:sport.icon};
  }).sort((a,b) => a.sport.localeCompare(b.sport) || a.label.localeCompare(b.label,'en'));

  if (!entries.length) {
    return [{json:{chat_id,text:'<b>➖ Unfollow</b>\n\nYou’re not following anyone yet.',
      buttons:[button('🏠 Sports','menu:sports'),...homeButtons]}}];
  }
  const pages = entries.length;
  const requestedPage = Number.isSafeInteger(request.page) ? request.page : 0;
  const page = Math.min(Math.max(0,requestedPage),pages-1);
  const entry = entries[page];
  const label = [...entry.label];
  const short = label.length > 28 ? label.slice(0,27).join('')+'…' : entry.label;
  const text = '<b>➖ Unfollow</b>\n\n'+entry.icon+' <b>'+escape(entry.label)+'</b>'+
    '\n\n'+(pages>1?'Use Previous / Next to choose a saved team or driver.\n':'')+
    'Tap Unfollow below to remove this choice. You can follow it again at any time.'+
    '\n\nSelection '+(page+1)+'/'+pages;
  // All five fields exist on every item: compatible with the native Telegram editor.
  // Navigation wraps at either end, while callbacks always remove a stable key.
  const buttons = [
    button('➖ Unfollow '+short,entry.callback),
    pages>1 ? button('⬅️ Previous','manage:follows:'+((page+pages-1)%pages)) : button('🔄 Refresh','manage:follows:0'),
    pages>1 ? button('Next ➡️','manage:follows:'+((page+1)%pages)) : button('➕ Follow more','menu:sports'),
    button('⭐ My follows','menu:follows'),button('🏠 Sports','menu:sports')
  ];
  return [{json:{chat_id,text,buttons}}];
}

const groups = [
  ['football','⚽ Football'],
  ['basketball','🏀 NBA'],
  ['f1','🏎️ Formula 1']
];
const heading = '<b>⭐ My follows</b>';
const pages = [];
let body = heading;
let count = 0;
for (const [sport,title] of groups) {
  const entries = prefs.filter(p => p.sport === sport).map(p => ({
    ...p,label:String(p.label || p.team_key || 'Unnamed selection').replace(/\s+/g,' ').trim().slice(0,150)
  })).sort((a,b) => a.label.localeCompare(b.label,'en'));
  if (!entries.length) continue;
  const section = '\n\n<b>' + title + '</b>';
  if ((body+section).length > 3400) { pages.push(body); body=heading; }
  body += section;
  for (const entry of entries) {
    const line = '\n• ' + escape(entry.label);
    if ((body+line).length > 3400) { pages.push(body); body=heading+section; }
    body += line;
    count++;
  }
}
if (!count) body += '\n\nYou’re not following anyone yet. Choose a sport below to get started.';
pages.push(body);
const buttons = [count
  ? button('➖ Unfollow','manage:follows:0')
  : button('🏠 Sports','menu:sports'), ...homeButtons];
return pages.map((text,i) => ({json:{chat_id,
  text:pages.length>1 ? text+'\n\nPage '+(i+1)+'/'+pages.length : text,
  buttons
}}));

parameters.query:
WITH claimed AS (
 INSERT INTO sports_radar.processed_updates(update_id,chat_id)
 SELECT $1::bigint,$2::text WHERE $4::boolean
 ON CONFLICT(update_id) DO NOTHING RETURNING update_id
)
SELECT $3::jsonb AS update WHERE EXISTS (SELECT 1 FROM claimed);
